def _iter_frames():
    """Yield the frames of the current call stack without reading source files.

    ``inspect.stack`` reads source lines from disk, which would itself trigger a
    blocking read (and infinite recursion). Walking ``f_back`` avoids any I/O.
    """
    frame = sys._getframe(1)  # deliberate, cheap stack walk (no source read)
    while frame is not None:
        yield frame
        frame = frame.f_back


def _in_pydev_wait_suspend() -> bool:
    """Return True if a PyDev debugger wait-suspend frame is on the stack."""
    for frame in _iter_frames():
        code = frame.f_code
        if code.co_name in {"do_wait_suspend", "_do_wait_suspend"}:
            return True
        if "pydevd" in code.co_filename:
            return True
    return False


def _in_pytest_assertion_rewrite() -> bool:
    """Return True if pytest's assertion-rewrite machinery is on the stack."""
    for frame in _iter_frames():
        filename = frame.f_code.co_filename
        if "_pytest" in filename and "rewrite" in filename:
            return True
    return False


def _in_file_loader() -> bool:
    """Return True if an import ``FileLoader`` is reading data on the stack."""
    if FileLoader is None:
        return False
    for frame in _iter_frames():
        self_obj = frame.f_locals.get("self")
        if isinstance(self_obj, FileLoader):
