    return False


def _is_std_stream(obj) -> bool:
    """Return True if ``obj`` is (the buffer of) stdout/stderr."""
    for std in (sys.stdout, sys.stderr, sys.__stdout__, sys.__stderr__):
        if std is None:
            continue
        if obj is std:
            return True
        buffer = getattr(std, "buffer", None)
        if buffer is not None and obj is buffer:
            return True
    return False


def _is_std_fd(fd) -> bool:
    """Return True if the file descriptor belongs to stdout/stderr."""
    if not isinstance(fd, int):
        return False
    if fd in (1, 2):
        return True
    for std in (sys.stdout, sys.stderr, sys.__stdout__, sys.__stderr__):
        if std is None:
            continue
        try:
            if std.fileno() == fd:
                return True
        except (OSError, ValueError, AttributeError):
            continue
    return False


